-- V28 — Dispatch audit gap fixes.
--  P0: manager-approval pages (qty + weight) rebuilt as real Forms — GP picker
--      + system-verdict context + Approve/Reject buttons that submit
--      status=APPROVED/REJECTED (via WorkflowActionButton.submitValues) and let
--      the workflow guard route. Replaces the old dead entity.update-field flips
--      + wrong-workflow transitions + a queue filtered on a status the engine
--      never writes (which left the manager's inbox permanently empty).
--  Minors: QC pre-load shows vehicle type + driver; sealing captures a
--      completion status + start/finish timestamps; Loading Progress filter
--      pruned of the dead DISPATCH_LOAD_ENTRY value.
-- Bodies served live from page_version, so this backfills fresh DBs. Idempotent.

-- sealing status + timestamps
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS sealing_status      VARCHAR(16) NULL;
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS sealing_started_at  DATETIME NULL;
ALTER TABLE gate_pass ADD COLUMN IF NOT EXISTS sealing_finished_at DATETIME NULL;
INSERT INTO entity_field_registry (id, tenant_id, entity_code, field_code, display_label, data_type, filterable, sortable, searchable, required, widget_kind)
SELECT (SELECT COALESCE(MAX(id),0) FROM entity_field_registry x)+ROW_NUMBER() OVER (ORDER BY c.fc),
       -1,'GatePass',c.fc,c.lbl,c.dt,0,1,0,0,c.wk
FROM (SELECT 'sealing_status' fc,'Sealing Status' lbl,'STRING' dt,'text' wk
      UNION ALL SELECT 'sealing_started_at','Sealing Start','DATETIME','datetime'
      UNION ALL SELECT 'sealing_finished_at','Sealing Finish','DATETIME','datetime') c
WHERE NOT EXISTS (SELECT 1 FROM entity_field_registry WHERE entity_code='GatePass' AND field_code=c.fc);
UPDATE m0_workflow_projection
SET field_map_json = JSON_MERGE_PATCH(COALESCE(field_map_json, JSON_OBJECT()),
  JSON_OBJECT('sealing_status',JSON_ARRAY('sealing_status'),
              'sealing_started_at',JSON_ARRAY('sealing_started_at'),
              'sealing_finished_at',JSON_ARRAY('sealing_finished_at')))
WHERE target_table='gate_pass' AND workflow_code IN ('M10.FGLoading','M10.PackLoading','M10.TankerOutbound')
  AND JSON_EXTRACT(field_map_json,'$.sealing_status') IS NULL;

UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "list", "title": "Loading In Progress — Inbox", "dataSource": {"type": "entity", "entity": "GatePass", "filter": {"field": "status", "op": "eq", "value": "LOADING_IN_PROGRESS"}}, "columns": [{"field": "id", "label": "#", "sortable": true}, {"field": "gp_number", "label": "GP #", "sortable": true}, {"field": "flow_variant_code", "label": "Flow", "sortable": true}, {"field": "vehicle_no", "label": "Vehicle", "sortable": true}, {"field": "driver_name", "label": "Driver", "sortable": true}, {"field": "status", "label": "Status", "sortable": true, "render": "badge", "colorMap": {"QC_CHECKED": "amber", "RECEIVED": "green", "RELEASED": "green", "ACCEPTED": "green", "ONBOARDED": "green", "DRAFT": "grey", "HOLD_CREDIT": "red", "PROVISIONAL": "amber", "RUNNING": "blue", "PLANNED": "grey", "MGR_APPROVED": "blue", "CLOSED": "grey", "CONDITIONAL_APPROVAL": "amber", "SUBMITTED": "blue", "REJECTED": "red", "CANCELLED": "red", "WON": "green", "RESOLVED": "green", "DELIVERED": "green", "LOST": "red", "ITEMS_LOGGED": "amber", "IN_PROGRESS": "blue", "CEO_APPROVED": "green", "GENERATED": "green", "QC_REJECTED": "red", "ON_HOLD": "amber", "ISSUED": "amber", "STORED": "green", "ACTIVE": "green", "HR_APPROVED": "blue", "APPROVED": "green"}}], "filters": [{"field": "status", "label": "Status", "type": "multi-select", "options": [{"value": "DISPATCH_LOAD_ENTRY", "label": "DISPATCH_LOAD_ENTRY"}]}], "rowActions": [{"label": "Loading In Progress", "action": "entity.update-field", "args": {"field": "status", "value": "LOADING_IN_PROGRESS"}, "color": "secondary"}, {"label": "📦 Fetch Order", "action": "page.open", "page": "aria:loading-order", "params": {"route": "row.route_id"}, "color": "primary"}], "pageSize": 25}'
WHERE pd.code='aria:loading-in-progress' AND pv.body_json NOT LIKE '%LOADING_IN_PROGRESS%';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Qty Difference — Manager Approval", "span": 12, "subtitle": "The system stopped these vehicles: loaded weight (W1-W2) differs from the OrderApp qty beyond the 0.4% tolerance. Pick the gate pass showing PMT_CHECK_PENDING_MANAGER, review the variance, add a reason, then RELEASE to billing or SEND BACK to reload.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (scan / pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "reference_no": "reference_no", "expected_weight_kg": "expected_weight_kg", "loaded_weight_kg": "loaded_weight_kg", "pmt_variance_pct": "pmt_variance_pct", "withinTolerance": "pmt_within_tolerance"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "reference_no", "label": "Order ID", "type": "text", "readOnly": true}, {"name": "expected_weight_kg", "label": "Expected Weight (kg)", "type": "text", "readOnly": true}, {"name": "loaded_weight_kg", "label": "Loaded (W1 - W2) kg", "type": "text", "readOnly": true}, {"name": "pmt_variance_pct", "label": "Variance %", "type": "text", "readOnly": true}, {"name": "withinTolerance", "label": "System Verdict", "type": "text", "readOnly": true}, {"name": "variance_reason", "label": "Manager Reason (required to release or reject)", "type": "textarea"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "✓ Approve & Release to Billing", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "PMT_CHECK_OK", "color": "primary", "submitValues": {"status": "APPROVED"}}, {"kind": "WorkflowActionButton", "label": "✗ Reject — Send Back to Reload", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "RELOAD_REQUIRED", "color": "error", "submitValues": {"status": "REJECTED"}}]}]}]}]}'
WHERE pd.code='aria:manager-qty-approval' AND pv.body_json NOT LIKE '%submitValues%';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Weight Verification — Manager Approval", "span": 12, "subtitle": "Final (third) weight captured at the exit. Pick the gate pass showing WEIGHMENT_3, confirm W3 against the second weight; if there\'s a difference, record the reason. APPROVE to send the vehicle to the gate, or REJECT it.", "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (scan / pick / type)", "type": "select", "required": true, "freeSolo": true, "scannable": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "instanceId": "workflow_instance_id", "w2_weight_kg": "w2_weight_kg", "w3_weight_kg": "w3_weight_kg", "variance_reason": "variance_reason"}}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "w2_weight_kg", "label": "Second Weight (kg)", "type": "text", "readOnly": true}, {"name": "w3_weight_kg", "label": "Third Weight (kg)", "type": "text", "readOnly": true}, {"name": "variance_reason", "label": "Weight-difference reason (if any)", "type": "textarea"}]}}, {"kind": "Stack", "direction": "row", "gap": 12, "children": [{"kind": "WorkflowActionButton", "label": "✓ Approve — Ready for Exit", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "READY_FOR_EXIT", "color": "primary", "submitValues": {"status": "APPROVED"}}, {"kind": "WorkflowActionButton", "label": "✗ Reject", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "REJECTED_BY_MANAGER", "color": "error", "submitValues": {"status": "REJECTED"}}]}]}]}]}'
WHERE pd.code='aria:manager-weight-approval' AND pv.body_json NOT LIKE '%submitValues%';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/QC"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "QC Pre-Load — Queue", "span": 12, "subtitle": "Vehicles awaiting QC pre-load approval. Approve records the loading supervisor + location; Reject needs a reason.", "children": [{"kind": "WorkflowQueueList", "persona": "QC", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Capture & Submit", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "flow_variant_code": "flow_variant_code", "instanceId": "workflow_instance_id", "vehicle_type": "vehicle_type", "driver_name": "driver_name"}, "scannable": true, "freeSolo": true}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_variant_code", "label": "Flow", "type": "text", "readOnly": true}, {"name": "vehicle_type", "label": "Vehicle Type", "type": "text", "readOnly": true}, {"name": "driver_name", "label": "Driver", "type": "text", "readOnly": true}, {"name": "loading_supervisor", "label": "Loading Supervisor", "type": "text", "visibleWhen": "#form.flow_variant_code == \'M10.TankerOutbound\'"}, {"name": "loading_tank_location", "label": "Loading Location", "type": "text"}, {"name": "qc_reject_reason", "label": "Reject Reason (only if rejecting)", "type": "textarea"}]}, "children": [{"kind": "WorkflowActionButton", "label": "Approve", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "QC_PRELOAD_APPROVED", "color": "primary"}, {"kind": "WorkflowActionButton", "label": "Reject", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "QC_PRELOAD_REJECTED", "color": "error"}]}]}]}]}'
WHERE pd.code='aria:qc-preload-approval' AND pv.body_json NOT LIKE '%vehicle_type%';
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "entity": "GatePass", "dataSources": [{"id": "q", "kind": "rest", "method": "GET", "url": "/api/workflow/queue/Dispatch"}], "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Sealing — Queue", "span": 12, "subtitle": "Loaded vehicles awaiting sealing (packing / FG). Record the seal number.", "children": [{"kind": "WorkflowQueueList", "persona": "Dispatch", "dataSource": "q", "pageSize": 25, "cardFields": ["gpNumber", "vehicleNo", "flowVariant", "currentState"]}]}, {"kind": "Section", "title": "Capture & Submit", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass # (pick one)", "type": "select", "required": true, "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicle_no": "vehicle_no", "flow_variant_code": "flow_variant_code", "instanceId": "workflow_instance_id"}, "scannable": true, "freeSolo": true}, {"name": "vehicle_no", "label": "Vehicle", "type": "text", "readOnly": true}, {"name": "flow_variant_code", "label": "Flow", "type": "text", "readOnly": true}, {"name": "sealing_no", "label": "Sealing No", "type": "text", "required": true}, {"name": "sealing_supervisor", "label": "Sealing Supervisor", "type": "text"}, {"name": "sealing_status", "label": "Sealing Completion Status", "type": "select", "options": [{"value": "IN_PROGRESS", "label": "In Progress"}, {"value": "COMPLETED", "label": "Completed"}]}, {"name": "sealing_started_at", "label": "Sealing Start", "type": "datetime"}, {"name": "sealing_finished_at", "label": "Sealing Finish", "type": "datetime"}, {"name": "seal_lock_status", "label": "Sealing Status", "type": "select", "options": [{"label": "Completed", "value": "AUTO_LOCK"}, {"label": "Seal No Updated", "value": "SEAL_NO_UPDATE"}]}]}, "children": [{"kind": "WorkflowActionButton", "label": "Sealing Done", "action": "workflow.transition", "instanceId": "{{form.instanceId}}", "targetState": "SEALING_DONE", "color": "primary"}]}]}]}]}'
WHERE pd.code='aria:sealing-process' AND pv.body_json NOT LIKE '%sealing_status%';
